    double weight;
    int age;
    std::string sex;
    static const std::unordered_map<std::string, std::vector<double>> BMI_std;
};


const std::unordered_map<std::string, std::vector<double>> FitnessTracker::BMI_std = {
    {"male", {20.0, 25.0}},
    {"female", {19.0, 24.0}}
};

