```python
import socket

class IpUtil:
    @staticmethod
    def is_valid_ipv4(ip_address: str) -> bool:
        try:
            socket.inet_pton(socket.AF_INET, ip_address)
            return True
        except OSError:
            return False

    @staticmethod
    def is_valid_ipv6(ip_address: str) -> bool:
        try:
            socket.inet_pton(socket.AF_INET6, ip_address)
            return True
        except OSError:
            return False

    @staticmethod
    def get_hostname(ip_address: str) -> str:
        if ip_address == "0.0.0.0":
            try:
                return socket.gethostname()
            except OSError:
                return ""

        try:
            # Python's getnameinfo abstracts the sockaddr_in struct creation.
            # Passing 0 as the port and 0 for flags matches the C++ behavior.
            host, _ = socket.getnameinfo((ip_address, 0), 0)
            return host
        except OSError:
            # C++ returns "" if inet_pton fails or if getnameinfo result != 0.
            # In Python, both cases raise OSError (or subclasses like socket.gaierror).
            return ""
