        users[username] = true;
        return true;
    }
}

bool SignInSystem::check_sign_in(const std::string& username) {
    auto result = users.find(username);
    if (result == users.end()) {
        return false;
    }
    else {
        return result->second;
    }
}

bool SignInSystem::all_signed_in() {
    for (const auto& pair : users) {
        if (!pair.second) {
            return false;
        }
