        return CombinationCalculator._factorial(n) // (CombinationCalculator._factorial(n - m) * CombinationCalculator._factorial(m))

    @staticmethod
    def _factorial(x):
        result = 1
        for i in range(1, x + 1):
            result *= i
        return result

    @staticmethod
    def countAll(n):
        if n < 0 or n > 63:
            return float('nan')
        if n != 63:
            return (1 << n) - 1
        else:
            return float('inf')

