                if self.cookies is not None:
                    json_object.update(self.cookies)
                f.write(json.dumps(json_object))
                f.flush()
                return True
        except OSError:
            return False

    def set_cookies(self, request):
        cookies_string = ""
        if self.cookies is not None:
