        x2, y2 = pos2[0], pos2[1]

        if not self.isValidPosition(x1, y1) or not self.isValidPosition(x2, y2):
            return False

        visited = [[False] * self.BOARD_SIZE[1] for _ in range(self.BOARD_SIZE[0])]
        return self.dfs(x1, y1, pos2, visited)

