#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <set>
#include <unordered_set>
#include <unordered_map>
#include <any>
#include <optional>
#include <sstream>
#include <typeinfo>

enum class ArgType {
    INTEGER,
    BOOLEAN,
    STRING
};

class ArgumentParser {
public:
    std::map<std::string, std::any> arguments;
    std::set<std::string> required;
    std::map<std::string, ArgType> types;

    ArgumentParser() = default;

    struct ParseResult {
        bool success;
        std::optional<std::set<std::string>> missing;
    };

    ParseResult parseArguments(const std::string& commandString) {
        std::vector<std::string> args = split(commandString, "\\s+");
        for (size_t i = 1; i < args.size(); i++) {
            std::string arg = args[i];
            if (startsWith(arg, "--")) {
                std::string sub = arg.substr(2);
                std::vector<std::string> keyValue = split(sub, "=");
                if (keyValue.size() == 2) {
                    arguments[keyValue[0]] = convertType(keyValue[0], keyValue[1]);
                } else {
                    arguments[keyValue[0]] = true;
                }
            } else if (startsWith(arg, "-")) {
                std::string key = arg.substr(1);
                if (i + 1 < args.size() && !startsWith(args[i + 1], "-")) {
                    arguments[key] = convertType(key, args[i + 1]);
                    i++;
                } else {
                    arguments[key] = true;
                }
            }
        }
        std::set<std::string> missingArgs = required;
        for (const auto& key : arguments) {
            missingArgs.erase(key.first);
        }
        if (!missingArgs.empty()) {
            return {false, missingArgs};
        }
        return {true, std::nullopt};
    }

    std::any getArgument(const std::string& key) {
        auto it = arguments.find(key);
        if (it != arguments.end()) {
            return it->second;
        }
        return {};  // null equivalent
    }

    void addArgument(const std::string& arg, bool isRequired, ArgType argType) {
        if (isRequired) {
            required.insert(arg);
        }
        types[arg] = argType;
    }

    std::any convertType(const std::string& arg, const std::string& value) {
        try {
            auto it = types.find(arg);
            if (it != types.end()) {
                ArgType type = it->second;
                if (type == ArgType::INTEGER) {
                    return std::stoi(value);
                } else if (type == ArgType::BOOLEAN) {
                    return value == "true";
                } else if (type == ArgType::STRING) {
                    return value;
                }
            }
        } catch (...) {
            return value;
        }
        return value;
    }

private:
    std::vector<std::string> split(const std::string& s, const std::string& delimiter) {
        std::vector<std::string> tokens;
        if (delimiter == "\\s+") {
            // Split on whitespace
            std::istringstream iss(s);
            std::string token;
            while (iss >> token) {
                tokens.push_back(token);
            }
        } else if (delimiter == "=") {
            // Split on = character
            std::string token;
            for (size_t i = 0; i < s.size(); i++) {
                if (s[i] == '=') {
                    tokens.push_back(token);
                    token.clear();
                } else {
                    token += s[i];
                }
            }
            tokens.push_back(token);
        }
        return tokens;
    }

    bool startsWith(const std::string& s, const std::string& prefix) {
        return s.size() >= prefix.size() && s.compare(0, prefix.size(), prefix) == 0;
    }
};

int main() {
    ArgumentParser parser;
    parser.addArgument("arg1", true, ArgType::INTEGER);
    parser.addArgument("arg2", false, ArgType::STRING);
    parser.addArgument("option1", false, ArgType::BOOLEAN);
