        while (!operatorStack.empty()) {
            postfixStack.push_back(std::string(1, operatorStack.top()));
            operatorStack.pop();
        }
    }

    bool isOperator(char ch) {
        return ch == '+' || ch == '-' || ch == '*' || ch == '/' || ch == '%';
    }

    bool compare(char op1, char op2) {
        char cur_op = (op1 == '%') ? '/' : op1;
        char peek_op = (op2 == '%') ? '/' : op2;
        int operat_priority[] = {0, 3, 2, 1, -1, 1, 0, 2};
        return operat_priority[peek_op - 40] >= operat_priority[cur_op - 40];
    }

private:
    double evaluatePostfix() {
        std::stack<double> stack;
        for (const std::string& token : postfixStack) {
            if (isOperator(token[0])) {
                double b = stack.top(); stack.pop();
                double a = stack.top(); stack.pop();
                stack.push(_calculate(a, b, token[0]));
            } else {
                stack.push(std::stod(token));
            }
        }
        double result = stack.top(); stack.pop();
        return result;
    }

    double _calculate(double a, double b, char op) {
        switch (op) {
            case '+': return a + b;
            case '-': return a - b;
            case '*': return a * b;
            case '/': return a / b;
            case '%': return std::fmod(a, b);
            default: throw std::invalid_argument("Unsupported operator: " + std::string(1, op));
        }
    }

public:
    std::string transform(std::string expression) {
        // Remove spaces
        std::string noSpaces;
        for (char c : expression) {
            if (c != ' ') noSpaces += c;
        }
        expression = noSpaces;

        // Replace '-' with '~'
        for (char& c : expression) {
            if (c == '-') c = '~';
        }

        if (!expression.empty() && expression[0] == '~' && expression.length() > 1 && expression[1] == '(') {
            expression[0] = '-';
            return "0" + expression;
        } else {
            return expression;
        }
    }
};
```

Key translation decisions:
- **`Deque<String> postfixStack`** → `std::deque<std::string>`: Java's `add()` appends to the tail; C++ `push_back()` does the same. Iteration order is preserved.
- **`Deque<Character> operatorStack`** and **`Deque<Double> stack`** → `std::stack<...>`: Both used as LIFO stacks (`push`/`pop`/`peek` → `push`/`pop`/`top`).
- **`Double.parseDouble`** → `std::stod`
- **Java's `%` on doubles** → `std::fmod`: Java's floating-point remainder operator maps directly to `std::fmod`.
- **`IllegalArgumentException`** → `std::invalid_argument`
- **`Character.isDigit`** → `std::isdigit` with `static_cast<unsigned char>` to avoid UB on negative char values.
- **`String.valueOf(char)`** → `std::string(1, char)`
- **`replaceAll(" ", "")` / `replaceAll("-", "~")`** → manual loops replacing the regex-based replacements with equivalent character-level logic.
- **`StringBuilder`** → `std::string` with `+=`

