        String xs = !rstr.isEmpty() ? "AND CENTS " + transTwo(rstr) + " " : "";
        if (lm.toString().trim().isEmpty()) {
            return "ZERO ONLY";
        } else {
            return lm.toString().trim() + " " + xs + "ONLY";
        }
