    bool withEndTag;

    static std::string trim(const std::string& s) {
        size_t start = s.find_first_not_of(" \t\n\r\f\v");
        if (start == std::string::npos) return "";
        size_t end = s.find_last_not_of(" \t\n\r\f\v");
        return s.substr(start, end - start + 1);
    }

    static std::string urlDecode(const std::string& s, const std::string& charset) {
        std::string result;
        for (size_t i = 0; i < s.size(); ++i) {
            if (s[i] == '+') {
                result += ' ';
            } else if (s[i] == '%' && i + 2 < s.size()) {
                try {
                    std::string hexStr = s.substr(i + 1, 2);
                    char decoded = static_cast<char>(std::stoi(hexStr, nullptr, 16));
                    result += decoded;
                    i += 2;
                } catch (const std::exception& e) {
                    result += s[i];
                }
            } else {
                result += s[i];
            }
        }
        return result;
    }

    static std::vector<std::string> split(const std::string& s, const std::string& delimiter) {
        std::vector<std::string> tokens;
        size_t start = 0;
        size_t end = s.find(delimiter);
        while (end != std::string::npos) {
            tokens.push_back(s.substr(start, end - start));
            start = end + delimiter.length();
            end = s.find(delimiter, start);
        }
        tokens.push_back(s.substr(start));
        return tokens;
    }

public:
    UrlPath() : withEndTag(false) {}

    void add(const std::string& segment) {
        segments.push_back(fixPath(segment));
    }

    void parse(const std::string& path, const std::string& charset) {
        if (!path.empty()) {
            if (path.back() == '/') {
                withEndTag = true;
            }

            std::string fixed = fixPath(path);
            if (!fixed.empty()) {
                std::vector<std::string> parts = split(fixed, "/");
                for (const auto& seg : parts) {
                    try {
                        std::string decodedSeg = urlDecode(seg, charset);
                        segments.push_back(decodedSeg);
                    } catch (const std::exception& e) {
                        std::cerr << e.what() << std::endl;
                    }
                }
            }
        }
    }

    static std::string fixPath(const std::string& path) {
        if (path.empty()) {
            return "";
        }

        std::string trimmed = trim(path);
        std::regex re("^/+|/+$");
        return std::regex_replace(trimmed, re, "");
    }

    std::vector<std::string> getSegments() const {
        return segments;
    }

    bool isWithEndTag() const {
        return withEndTag;
    }
};
