```cpp
std::string decimalToHex(int decimalNum) {
    if (decimalNum == 0) return "0";
    unsigned int uNum = static_cast<unsigned int>(decimalNum);
    std::string result;
    while (uNum > 0) {
        int rem = uNum % 16;
        char c = (rem < 10) ? ('0' + rem) : ('a' + rem - 10);
