// RAII wrapper for libzip's zip_t
class ZipFile {
private:
    zip_t* archive_;
    bool valid_;

public:
    explicit ZipFile(const std::string& path) : archive_(nullptr), valid_(false) {
        int err = 0;
        archive_ = zip_open(path.c_str(), ZIP_RDONLY, &err);
        if (archive_ == nullptr) {
            valid_ = false;
        } else {
            valid_ = true;
        }
    }

    ~ZipFile() {
        if (archive_ != nullptr) {
            zip_close(archive_);
        }
    }

    // Non-copyable
    ZipFile(const ZipFile&) = delete;
    ZipFile& operator=(const ZipFile&) = delete;

    // Movable
    ZipFile(ZipFile&& other) noexcept : archive_(other.archive_), valid_(other.valid_) {
        other.archive_ = nullptr;
        other.valid_ = false;
    }

    ZipFile& operator=(ZipFile&& other) noexcept {
        if (this != &other) {
            if (archive_) zip_close(archive_);
            archive_ = other.archive_;
            valid_ = other.valid_;
            other.archive_ = nullptr;
            other.valid_ = false;
        }
        return *this;
    }

    bool isValid() const { return valid_; }

    zip_int64_t getNumEntries() const {
        if (!valid_) return 0;
        return zip_get_num_entries(archive_, 0);
    }

    struct Entry {
        std::string name;
        bool is_directory;
        zip_uint64_t index;
    };

    std::vector<Entry> getEntries() const {
        std::vector<Entry> entries;
        if (!valid_) return entries;

        zip_int64_t num = zip_get_num_entries(archive_, 0);
        for (zip_int64_t i = 0; i < num; i++) {
            Entry entry;
            const char* name = zip_get_name(archive_, i, 0);
            if (name == nullptr) continue;
            entry.name = name;
            entry.index = static_cast<zip_uint64_t>(i);
            entry.is_directory = (!entry.name.empty() && entry.name.back() == '/');
            entries.push_back(entry);
        }
        return entries;
    }

    Entry getEntry(const std::string& fileName) const {
        Entry entry;
        entry.index = static_cast<zip_uint64_t>(-1);
        entry.is_directory = false;

        if (!valid_) return entry;

        zip_int64_t idx = zip_name_locate(archive_, fileName.c_str(), 0);
        if (idx < 0) {
            return entry;
        }

        const char* name = zip_get_name(archive_, idx, 0);
        if (name == nullptr) return entry;

        entry.name = name;
        entry.index = static_cast<zip_uint64_t>(idx);
        entry.is_directory = (!entry.name.empty() && entry.name.back() == '/');
        return entry;
    }

    bool hasEntry(const std::string& fileName) const {
        if (!valid_) return false;
        return zip_name_locate(archive_, fileName.c_str(), 0) >= 0;
    }

    bool extractEntry(const Entry& entry, const fs::path& outputPath) const {
        if (!valid_ || entry.index == static_cast<zip_uint64_t>(-1)) return false;

        zip_file_t* file = zip_fopen_index(archive_, entry.index, 0);
        if (file == nullptr) return false;

        std::ofstream out(outputPath, std::ios::binary | std::ios::trunc);
        if (!out.is_open()) {
