            return false;
        }

        char buffer[1024];
        zip_int64_t len;
        while ((len = zip_fread(file, buffer, sizeof(buffer))) > 0) {
            out.write(buffer, len);
        }

        zip_fclose(file);
        out.close();
        return true;
    }

    zip_t* handle() const { return archive_; }
