    ZipFile(const ZipFile&) = delete;
    ZipFile& operator=(const ZipFile&) = delete;

    ZipFile(ZipFile&& other) noexcept : archive_(other.archive_), valid_(other.valid_) {
        other.archive_ = nullptr;
        other.valid_ = false;
    }

    ZipFile& operator=(ZipFile&& other) noexcept {
        if (this != &other) {
            if (archive_) zip_close(archive_);
            archive_ = other.archive_;
            valid_ = other.valid_;
            other.archive_ = nullptr;
            other.valid_ = false;
        }
        return *this;
    }

    bool isValid() const { return valid_; }

    struct Entry {
        std::string name;
        bool is_directory;
        zip_uint64_t index;
        bool valid;

        Entry() : is_directory(false), index(static_cast<zip_uint64_t>(-1)), valid(false) {}
    };

    std::vector<Entry> getEntries() const {
        std::vector<Entry> entries;
        if (!valid_) return entries;

        zip_int64_t num = zip_get_num_entries(archive_, 0);
        for (zip_int64_t i = 0; i < num; i++) {
            Entry entry;
            const char* name = zip_get_name(archive_, static_cast<zip_uint64_t>(i), 0);
            if (name == nullptr) continue;
            entry.name = name;
            entry.index = static_cast<zip_uint64_t>(i);
            entry.is_directory = (!entry.name.empty() && entry.name.back() == '/');
            entry.valid = true;
            entries.push_back(entry);
        }
        return entries;
    }

    Entry getEntry(const std::string& fileName) const {
        Entry entry;
        if (!valid_) return entry;

        zip_int64_t idx = zip_name_locate(archive_, fileName.c_str(), 0);
        if (idx < 0) return entry;

        const char* name = zip_get_name(archive_, static_cast<zip_uint64_t>(idx), 0);
        if (name == nullptr) return entry;

        entry.name = name;
        entry.index = static_cast<zip_uint64_t>(idx);
        entry.is_directory = (!entry.name.empty() && entry.name.back() == '/');
        entry.valid = true;
        return entry;
    }

    bool extractEntry(const Entry& entry, const fs::path& outputPath) const {
        if (!valid_ || !entry.valid) return false;

        zip_file_t* file = zip_fopen_index(archive_, entry.index, 0);
        if (file == nullptr) return false;

        std::ofstream out(outputPath, std::ios::binary | std::ios::trunc);
        if (!out.is_open()) {
            zip_fclose(file);
            return false;
        }

        char buffer[1024];
        zip_int64_t len;
        while ((len = zip_fread(file, buffer, sizeof(buffer))) > 0) {
            out.write(buffer, len);
        }

        zip_fclose(file);
        out.close();
        return out.good();
    }
};

class ZipFileProcessor {
private:
    static Logger logger;
    fs::path zipFilePath_;

    std::unique_ptr<ZipFile> readZipFile() {
        if (!fs::exists(zipFilePath_)) {
            logger.severe("Zip file does not exist: " + fs::absolute(zipFilePath_).string());
            return nullptr;
        }

        auto zipFile = std::make_unique<ZipFile>(zipFilePath_.string());
        if (!zipFile->isValid()) {
            logger.severe("Failed to read the zip file: " + fs::absolute(zipFilePath_).string());
            return nullptr;
        }
        return zipFile;
    }

public:
    explicit ZipFileProcessor(const std::string& zipFileName)
        : zipFilePath_(zipFileName) {}

    bool extractAll(const std::string& outputDir) {
        fs::path outputDirPath(outputDir);

        auto zipFile = readZipFile();
        if (zipFile == nullptr) return false;

        if (!fs::exists(outputDirPath)) {
            try {
                fs::create_directories(outputDirPath);
                logger.info("Created output directory: " + fs::absolute(outputDirPath).string());
            } catch (const fs::filesystem_error& e) {
                logger.severe("Failed to create output directory: " + fs::absolute(outputDirPath).string(), e.what());
                return false;
            }
        }

        auto entries = zipFile->getEntries();
        for (const auto& entry : entries) {
            fs::path filePath = outputDirPath / entry.name;
            try {
                if (entry.is_directory) {
                    if (!fs::exists(filePath)) {
                        fs::create_directories(filePath);
                        logger.info("Created directory: " + fs::absolute(filePath).string());
                    }
                } else {
                    if (zipFile->extractEntry(entry, filePath)) {
                        logger.info("Extracted file: " + fs::absolute(filePath).string());
                    } else {
                        logger.severe("Failed to process entry: " + entry.name);
                    }
                }
            } catch (const fs::filesystem_error& e) {
                logger.severe("Failed to process entry: " + entry.name, e.what());
            }
        }

        return true;
    }

    bool extractFile(const std::string& fileName, const std::string& outputDir) {
        fs::path outputDirPath(outputDir);
        fs::path filePath = outputDirPath / fileName;

        auto zipFile = readZipFile();
        if (zipFile == nullptr) return false;

        auto entry = zipFile->getEntry(fileName);
        if (!entry.valid) {
            logger.warning("File not found in zip: " + fileName);
            return false;
        }

        if (filePath.has_parent_path() && !fs::exists(filePath.parent_path())) {
            try {
                fs::create_directories(filePath.parent_path());
                logger.info("Created parent directory: " + fs::absolute(filePath.parent_path()).string());
            } catch (const fs::filesystem_error& e) {
                logger.severe("Failed to create parent directory: " + fs::absolute(filePath.parent_path()).string(), e.what());
                return false;
            }
        }

        if (zipFile->extractEntry(entry, filePath)) {
            logger.info("Extracted file: " + fs::absolute(filePath).string());
            return true;
        } else {
            logger.severe("Failed to extract file: " + fileName);
            return false;
        }
    }
};

Logger ZipFileProcessor::logger("ZipFileProcessor");
