        // Create new filename: split on '.' and add '_process.csv'
        std::string base_name = save_file_name.substr(0, save_file_name.find('.'));
        std::string new_file_name = base_name + "_process.csv";

        return write_csv(new_data, new_file_name);
    }

private:
    std::vector<std::string> parse_csv_line(const std::string& line) {
        std::vector<std::string> result;
        std::string field;
        bool in_quotes = false;

        for (size_t i = 0; i < line.size(); ++i) {
            char c = line[i];
            if (in_quotes) {
                if (c == '"') {
                    if (i + 1 < line.size() && line[i + 1] == '"') {
                        field += '"';
                        ++i;
                    } else {
                        in_quotes = false;
                    }
                } else {
                    field += c;
                }
            } else {
                if (c == '"') {
                    in_quotes = true;
                } else if (c == ',') {
                    result.push_back(field);
                    field.clear();
                } else {
                    field += c;
                }
            }
        }
        result.push_back(field);
        return result;
    }

    std::ofstream& write_csv_row(std::ofstream& file, const std::vector<std::string>& row) {
        for (size_t i = 0; i < row.size(); ++i) {
            if (i > 0) file << ",";
            if (needs_quoting(row[i])) {
                file << "\"" << escape_quotes(row[i]) << "\"";
            } else {
                file << row[i];
            }
        }
        return file;
    }

    bool needs_quoting(const std::string& field) {
        return field.find(',') != std::string::npos ||
               field.find('"') != std::string::npos ||
               field.find('\n') != std::string::npos;
    }

    std::string escape_quotes(const std::string& field) {
        std::string result;
        for (char c : field) {
            if (c == '"') {
                result += "\"\"";
            } else {
                result += c;
            }
        }
        return result;
    }

    std::string to_upper(const std::string& s) {
        std::string result = s;
        std::transform(result.begin(), result.end(), result.begin(), [](unsigned char c) {
            return std::toupper(c);
        });
