            double d1 = data1[i] - mean1;
            double d2 = data2[i] - mean2;
            numerator += d1 * d2;
            sum_sq1 += d1 * d1;
            sum_sq2 += d2 * d2;
        }
        double denominator = std::sqrt(sum_sq1) * std::sqrt(sum_sq2);

        return denominator != 0 ? numerator / denominator : 0.0;
    }

    static double skewness(const std::vector<double>& data) {
        int n = data.size();
        double mean = std::accumulate(data.begin(), data.end(), 0.0) / n;
        double variance = 0.0;
        double sum_cubed = 0.0;
        for (const auto& x : data) {
            double d = x - mean;
            variance += d * d;
            sum_cubed += d * d * d;
        }
        variance /= n;
        double std_deviation = std::sqrt(variance);

        return std_deviation != 0 ? sum_cubed * n / ((n - 1) * (n - 2) * std_deviation * std_deviation * std_deviation) : 0.0;
    }

    static double kurtosis(const std::vector<double>& data) {
        int n = data.size();
        double mean = std::accumulate(data.begin(), data.end(), 0.0) / n;
        double sum_sq = 0.0;
        for (const auto& x : data) {
            double d = x - mean;
            sum_sq += d * d;
