The user wants to translate a Python class `GomokuGame` to C++.
The class has:
- `__init__(self, board_size)`: initializes the board with spaces and sets `current_player` to 'X'.
- `make_move(self, row, col)`: places the current player's symbol if the cell is empty, then switches the player. Returns True if valid, False otherwise.
- `check_winner(self)`: iterates over the board, checks 4 directions for 5 in a row. Returns the symbol of the winner or None.
- `_check_five_in_a_row(self, row, col, direction)`: checks if there are 5 consecutive symbols starting from (row, col) in the given direction (dx, dy). Returns True or False.

Let's design the C++ class.
```cpp
#include <vector>
#include <string>
#include <optional>
#include <tuple>

class GomokuGame {
public:
    GomokuGame(int board_size) 
        : board_size(board_size), 
          board(board_size, std::vector<char>(board_size, ' ')), 
          current_player('X') {}

    bool make_move(int row, int col) {
        if (board[row][col] == ' ') {
            board[row][col] = current_player;
            current_player = (current_player == 'X') ? 'O' : 'X';
            return true;
        }
        return false;
    }

    std::optional<char> check_winner() {
        std::vector<std::tuple<int, int>> directions = {
            {0, 1}, {1, 0}, {1, 1}, {1, -1}
        };
        for (int row = 0; row < board_size; ++row) {
            for (int col = 0; col < board_size; ++col) {
                if (board[row][col] != ' ') {
                    for (const auto& direction : directions) {
                        if (_check_five_in_a_row(row, col, direction)) {
                            return board[row][col];
                        }
                    }
                }
            }
        }
        return std::nullopt;
    }

private:
    bool _check_five_in_a_row(int row, int col, const std::tuple<int, int>& direction) {
        int dx = std::get<0>(direction);
        int dy = std::get<1>(direction);
        int count = 1;
        char symbol = board[row][col];
        for (int i = 1; i < 5; ++i) {
            int new_row = row + dx * i;
            int new_col = col + dy * i;
            if (!(0 <= new_row && new_row < board_size && 0 <= new_col && new_col < board_size)) {
                return false;
            }
            if (board[new_row][new_col] != symbol) {
                return false;
            }
            count++;
        }
        return count == 5;
    }

    int board_size;
    std::vector<std::vector<char>> board;
    char current_player;
};
```

