class SplitSentence {
public:
    std::vector<std::string> split_sentences(const std::string& sentences_string) {
        std::vector<std::string> result;
        std::string current;

        for (size_t i = 0; i < sentences_string.size(); ++i) {
            char c = sentences_string[i];

            // Check if this is a split point: whitespace preceded by . or ?
            if (c == ' ' && i > 0 && (sentences_string[i-1] == '.' || sentences_string[i-1] == '?')) {
                // Check negative lookbehind: (?<![A-Z][a-z]\.)
                // The 3 characters before the space should NOT be [A-Z][a-z].
                bool abbrev1 = false;
                if (i >= 3) {
                    char c3 = sentences_string[i-3];
                    char c2 = sentences_string[i-2];
                    char c1 = sentences_string[i-1];
                    if (c3 >= 'A' && c3 <= 'Z' && c2 >= 'a' && c2 <= 'z' && c1 == '.') {
                        abbrev1 = true;
                    }
                }

                // Check negative lookbehind: (?<!\w\.\w.)
                // The 4 characters before the space should NOT be \w.\w.
                bool abbrev2 = false;
                if (i >= 4) {
                    char c4 = sentences_string[i-4];
                    char c3 = sentences_string[i-3];
                    char c2 = sentences_string[i-2];
                    char c1 = sentences_string[i-1];
                    if (iswalnum(c4) && c3 == '.' && iswalnum(c2) && c1 == '.') {
                        abbrev2 = true;
                    }
                }

                if (!abbrev1 && !abbrev2) {
                    result.push_back(current);
                    current = "";
                    continue;
                }
            }

            current += c;
        }

        if (!current.empty()) {
            result.push_back(current);
        }

        return result;
    }

    int count_words(const std::string& sentence) {
        // Remove non-letter characters (keep a-zA-Z and spaces)
        std::string cleaned;
        for (char c : sentence) {
            if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == ' ') {
                cleaned += c;
            }
        }

        // Split by whitespace and count
        int count = 0;
        bool in_word = false;
        for (char c : cleaned) {
            if (c == ' ') {
                in_word = false;
            } else {
                if (!in_word) {
                    count++;
                    in_word = true;
                }
            }
        }

        return count;
    }

    int process_text_file(const std::string& sentences_string) {
        std::vector<std::string> sentences = split_sentences(sentences_string);
        int max_count = 0;
        for (const auto& sentence : sentences) {
            int count = count_words(sentence);
            if (count > max_count) {
                max_count = count;
            }
        }
        return max_count;
    }
};
