#include <string>
#include <vector>
#include <tuple>
#include <sqlite3.h>
#include <stdexcept>

class MovieTicketDB {
private:
    sqlite3* connection;

public:
    MovieTicketDB(const std::string& db_name) {
        int rc = sqlite3_open(db_name.c_str(), &connection);
        if (rc != SQLITE_OK) {
            std::string err_msg = "Cannot open database: " + std::string(sqlite3_errmsg(connection));
            sqlite3_close(connection);
            throw std::runtime_error(err_msg);
        }
        create_table();
    }

    ~MovieTicketDB() {
        if (connection) {
            sqlite3_close(connection);
        }
    }

    // Disable copy constructor and copy assignment to prevent double free
    MovieTicketDB(const MovieTicketDB&) = delete;
    MovieTicketDB& operator=(const MovieTicketDB&) = delete;

    void create_table() {
        const char* sql = R"(
            CREATE TABLE IF NOT EXISTS tickets (
                id INTEGER PRIMARY KEY,
                movie_name TEXT,
                theater_name TEXT,
                seat_number TEXT,
                customer_name TEXT
            )
        )";
        char* err_msg = nullptr;
        int rc = sqlite3_exec(connection, sql, nullptr, nullptr, &err_msg);
        if (rc != SQLITE_OK) {
            std::string err_str = err_msg;
            sqlite3_free(err_msg);
            throw std::runtime_error("SQL error: " + err_str);
        }
    }

    void insert_ticket(const std::string& movie_name, const std::string& theater_name, const std::string& seat_number, const std::string& customer_name) {
        const char* sql = "INSERT INTO tickets (movie_name, theater_name, seat_number, customer_name) VALUES (?, ?, ?, ?)";
        sqlite3_stmt* stmt;
        int rc = sqlite3_prepare_v2(connection, sql, -1, &stmt, nullptr);
        if (rc != SQLITE_OK) {
            throw std::runtime_error("Failed to prepare statement: " + std::string(sqlite3_errmsg(connection)));
        }

        sqlite3_bind_text(stmt, 1, movie_name.c_str(), -1, SQLITE_TRANSIENT);
        sqlite3_bind_text(stmt, 2, theater_name.c_str(), -1, SQLITE_TRANSIENT);
        sqlite3_bind_text(stmt, 3, seat_number.c_str(), -1, SQLITE_TRANSIENT);
        sqlite3_bind_text(stmt, 4, customer_name.c_str(), -1, SQLITE_TRANSIENT);

        rc = sqlite3_step(stmt);
        if (rc != SQLITE_DONE) {
            sqlite3_finalize(stmt);
            throw std::runtime_error("Failed to execute statement: " + std::string(sqlite3_errmsg(connection)));
        }

        sqlite3_finalize(stmt);
    }

    std::vector<std::tuple<int, std::string, std::string, std::string, std::string>> search_tickets_by_customer(const std::string& customer_name) {
        const char* sql = "SELECT * FROM tickets WHERE customer_name = ?";
        sqlite3_stmt* stmt;
        int rc = sqlite3_prepare_v2(connection, sql, -1, &stmt, nullptr);
        if (rc != SQLITE_OK) {
            throw std::runtime_error("Failed to prepare statement: " + std::string(sqlite3_errmsg(connection)));
        }

        sqlite3_bind_text(stmt, 1, customer_name.c_str(), -1, SQLITE_TRANSIENT);

        std::vector<std::tuple<int, std::string, std::string, std::string, std::string>> tickets;
        while ((rc = sqlite3_step(stmt)) == SQLITE_ROW) {
            int id = sqlite3_column_int(stmt, 0);
            std::string movie_name = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 1));
            std::string theater_name = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 2));
            std::string seat_number = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 3));
            std::string customer_name = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 4));
            tickets.emplace_back(id, movie_name, theater_name, seat_number, customer_name);
        }

        if (rc != SQLITE_DONE) {
            sqlite3_finalize(stmt);
            throw std::runtime_error("Failed to fetch data: " + std::string(sqlite3_errmsg(connection)));
        }

        sqlite3_finalize(stmt);
        return tickets;
    }

    void delete_ticket(int ticket_id) {
        const char* sql = "DELETE FROM tickets WHERE id = ?";
        sqlite3_stmt* stmt;
        int rc = sqlite3_prepare_v2(connection, sql, -1, &stmt, nullptr);
        if (rc != SQLITE_OK) {
            throw std::runtime_error("Failed to prepare statement: " + std::string(sqlite3_errmsg(connection)));
        }

        sqlite3_bind_int(stmt, 1, ticket_id);

        rc = sqlite3_step(stmt);
        if (rc != SQLITE_DONE) {
            sqlite3_finalize(stmt);
            throw std::runtime_error("Failed to execute statement: " + std::string(sqlite3_errmsg(connection)));
        }

        sqlite3_finalize(stmt);
    }
};
